export function endingLeftBy(
  comments: readonly { readonly body: string }[],
  runId: number,
  readers: EndingWalkReaders,
): boolean {
  return comments.some(
    (comment) => !readers.quoted(comment.body) && readers.ended(comment.body)?.run === runId,
