    void withAsk;
    expect(
      askSuperseded([at(A, human("/reviewer")), machine("CLAIM 9 RUN 7"), machine("ENDED handoff ANSWERS 9")], readers, 9, "reviewer"),
    ).toBe("handed-off");
  });

  test("the dispatched agent's own verdict already on the thread is superseded (#282)", () => {
    const thread = [at(A, human("/reviewer")), machine("CLAIM 9 RUN 7"), machine("RESULT done BY reviewer ANSWERS 9")];
    expect(askSuperseded(thread, readers, 9, "reviewer", true)).toBe("own-verdict");
  });

  test("a red CI run refutes the standing verdict and the retry goes", () => {
    const thread = [at(A, human("/reviewer")), machine("CLAIM 9 RUN 7"), machine("RESULT done BY reviewer ANSWERS 9")];
    expect(askSuperseded(thread, readers, 9, "reviewer", false)).toBeUndefined();
  });

  test("another agent's verdict on the quoted ask is the fix cycle, and goes", () => {
    const thread = [at(A, human("/engineer")), machine("CLAIM 9 RUN 7"), machine("RESULT done BY engineer ANSWERS 9")];
    expect(askSuperseded(thread, readers, 9, "reviewer", true)).toBeUndefined();
  });

  test("a machinery answer with no agent on it reads as the dispatched agent's own", () => {
    const thread = [at(A, human("/reviewer")), machine("CLAIM 9 RUN 7"), machine("ENDED done ANSWERS 9")];
    expect(askSuperseded(thread, readers, 9, "reviewer")).toBe("own-verdict");
  });

  test("a newer ask still open supersedes the quoted one", () => {
    const thread = [at(A, human("/reviewer")), at(newer, human("/engineer"))];
